-- 01_park_and_reference.sql: Park row (final prices, MaxOccupancy 440), zones, rides, games, venues, items. Generated by tools/gen_test_data.py.
USE theme_park;
SET NAMES utf8mb4;
-- Price list. File 15 sets the same values, so a database loaded from scratch has one price list from day one.
UPDATE MembershipTier SET AnnualPrice = CASE Tier WHEN 'Basic' THEN 69.00 WHEN 'Plus' THEN 89.00 WHEN 'Premier' THEN 179.00 END WHERE Tier IN ('Basic', 'Plus', 'Premier');
